const NotificationCard: React.FC<{
  x: number;
  y: number;
  scale: number;
  type: "message" | "calendar";
  delay: number;
  bg: string;
  config: { stiffness: number; damping: number };
}> = ({ x, y, scale, type, delay, bg, config }) => {
  const frame = useCurrentFrame();
  const { fps, height } = useVideoConfig();

  // Falling Physics
  // We start well above the screen (-height)
  const dropProgress = spring({
    frame: frame - delay,
    fps,
    config: {
      stiffness: config.stiffness,
      damping: config.damping,
      mass: 1.2, // Slightly heavier feel
    },
  });

  const translateY = interpolate(dropProgress, [0, 1], [-height * 0.8, y]);
  
  // Shadow grows as it gets closer (simulating height)
  // Scaled by the object size (larger/closer objects cast bigger shadows)
  const baseBlur = interpolate(dropProgress, [0, 1], [50, 20]);
  const scaledBlur = baseBlur * scale; 
  const shadowOpacity = interpolate(dropProgress, [0, 1], [0.1, 0.2]);

  // Fade in slightly at the very start so they don't pop into existence
  const opacity = interpolate(frame - delay, [0, 5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  if (frame < delay) return null;

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: 0, // Animated via transform
        transform: `translateY(${translateY}px) scale(${scale})`,
        width: 320,
        height: 80,
        backgroundColor: bg,
        borderRadius: 22,
        display: "flex",
        alignItems: "center",
        padding: "0 16px",
        gap: 16,
        boxShadow: `0 ${10 * scale}px ${scaledBlur}px rgba(0,0,0,${shadowOpacity})`,
        fontFamily: "Inter",
        zIndex: Math.round(scale * 100), // Larger scale on top
        willChange: "transform",
      }}
    >
      {/* Icon Area */}
      {type === "message" ? <MessageIcon /> : <CalendarIcon />}

      {/* Text Area */}
      <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
        <span style={{ fontSize: 16, fontWeight: 700, color: "#000" }}>
          Notification
        </span>
        <span style={{ fontSize: 15, fontWeight: 400, color: "#444" }}>
          do this task
        </span>
      </div>
    </div>
  );
};

// --- Main Composition ---

const NotificationRain: React.FC<NotificationRainProps> = ({
  backgroundColor = "#FFD60A", // Vibrant Yellow
  transparentBackground = false,
  primaryTextColor = "#000000",
  cardColor = "#F2F2F7", // iOS System Gray 6 / White-ish
  durationInSeconds = 15,
  staggerDelay = 5,
  springStiffness = 140,
  springDamping = 16,
}) => {
  useFontLoader(["Inter"]);

  const { width, height } = useVideoConfig();
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Fixed positions simulating the chaotic pile from reference with enhanced depth scales
  const notifications = useMemo(() => {
    const cx = width / 2;
    const cy = height / 2;
    const cardW = 320;
    const cardH = 80;

    // Helper to center the card on the coordinate
    const p = (relX: number, relY: number, s: number, t: "message" | "calendar") => ({
      x: relX * width - (cardW / 2),
      y: relY * height - (cardH / 2),
      // Scale multiplied by 1.4 to make elements proportionately bigger as requested
      scale: s * 1.4,
      type: t,
    });

    return [
      // Deep Background (Small - "Far away")
      p(0.25, 0.35, 0.55, "calendar"),
      p(0.75, 0.40, 0.6, "message"),
      p(0.45, 0.25, 0.5, "message"), // Extra small high up

      // Mid Ground (Normal size)
      p(0.12, 0.15, 0.9, "message"),  // Top Left
      p(0.88, 0.18, 0.95, "calendar"), // Top Right
      p(0.5, 0.12, 0.85, "calendar"),  // Top Centerish

      // Foreground (Large - "Close")
      p(0.15, 0.75, 1.35, "calendar"), // Bottom Left Area
      p(0.85, 0.65, 1.4, "message"),   // Right Mid

      // Extreme Foreground (Very close, partially offscreen/border)
      p(0.5, 0.88, 1.7, "message"),    // Bottom center, huge
      p(0.02, 0.55, 1.6, "message"),   // Left edge, huge
    ];
  }, [width, height]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        overflow: "hidden",
      }}
    >
      {/* Background Cards Layer */}
      {notifications.map((item, i) => (
        <NotificationCard
          key={i}
          x={item.x}
          y={item.y}
          scale={item.scale}
          type={item.type}
          delay={i * staggerDelay}
          bg={cardColor}
          config={{ stiffness: springStiffness, damping: springDamping }}
        />
      ))}

      {/* Center Text Layer */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          zIndex: 1000, 
          pointerEvents: "none", 
        }}
      >
        <h1
          style={{
            fontSize: 72,
            fontWeight: 800,
            color: primaryTextColor,
            margin: 0,
            textAlign: "center",
            letterSpacing: -1.5,
            textShadow: "0 20px 40px rgba(0,0,0,0.1)", // Very subtle lift
          }}
        >
          to drown in tasks
        </h1>
      </div>
    </AbsoluteFill>
  );
};

export default NotificationRain;